// Client-safe types for an AI conversation transcript shown under a writing
// (no filesystem access). Transcripts are generated by
// scripts/export-claude-chat.py.

export interface TranscriptStats {
  prompts: number;
  replies: number;
  toolCalls: number;
  start: string; // ISO timestamps of the first and last message
  end: string;
}

export type TranscriptMessage =
  | {
      role: "user";
      kind: "prompt" | "midturn"; // midturn: sent while the agent was working
      text: string;
      images: string[];
      ts: string;
    }
  | { role: "assistant"; text: string; tools: string[]; ts: string }
  | { role: "event"; text: string; ts: string };

export interface Transcript {
  stats: TranscriptStats;
  messages: TranscriptMessage[];
}

export function transcriptHours(stats: TranscriptStats): string {
  const ms = Date.parse(stats.end) - Date.parse(stats.start);
  const h = Math.floor(ms / 3_600_000);
  const m = Math.round((ms % 3_600_000) / 60_000);
  return h ? `${h}h ${m}m` : `${m}m`;
}
